\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs40\f3 {\cf2\ltrch Text Input and Attribute Viewer}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This module lets you enter simple English sentences, convert them into Thoughts and Links, and inspect the attributes of any selected Thought.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch The purpose of this tool is to make it easier to see how the system represents knowledge internally.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Entering knowledge}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch Type a simple sentence into the input box and submit it.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch The system will attempt to:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch identify the source Thought}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch identify the relationship type}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch identify the target Thought}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch singularize words where appropriate}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch convert the sentence into one or more internal Links}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\ltrch For example:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Dogs are mammals}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch is interpreted as:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? is-a \u8594? mammal]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch while:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Dogs are brown}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch is interpreted as:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? is \u8594? brown]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch In general, category relationships such as \ldblquote dogs are mammals\rdblquote  become }{\b\ltrch is-a}{\ltrch  links, while descriptive relationships such as \ldblquote dogs are brown\rdblquote  become }{\b\ltrch is}{\ltrch  links.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Similarly:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Fido is a dog}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch becomes:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [Fido \u8594? is-a \u8594? dog]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch and:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Dogs have fur}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch becomes:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? has \u8594? fur]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Parsed link display}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch When a sentence is entered, the module shows the Link or Links which were created. This lets you verify that the sentence was understood correctly.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This display is important because English is ambiguous. The parsed result confirms:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch singularization}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the relationship chosen}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the actual internal representation stored in memory}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch A multi-line parsed-link display acts as a running history of recently added knowledge.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Viewing attributes of a Thought}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch You may select a Thought and view its attributes.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This does more than show only the Links directly attached to that Thought. Depending on the current implementation, the system may also show inherited or implied attributes.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch For example, if the system knows:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? is-a \u8594? mammal]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [mammal \u8594? is \u8594? warm-blooded]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? has \u8594? fur]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [Fido \u8594? is-a \u8594? dog]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch then selecting }{\b\ltrch Fido}{\ltrch  may show attributes such as:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch dog}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch mammal}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch warm-blooded}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch fur}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch even though some of these were never entered directly for Fido.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This is one of the main purposes of the module: to show how connected knowledge allows new information to be derived from existing structure.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Analog strength}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch Each displayed attribute may include a visual indication of strength or confidence.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This reflects the fact that Links are not necessarily all-or-nothing. A relationship may be:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch newly learned and weak}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch reinforced and strong}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch fading due to lack of use}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\ltrch The background bar graph behind an attribute shows this strength visually.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This helps demonstrate that the system is not simply storing rigid symbolic facts. Each Link can carry a graded level of confidence.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch What this module demonstrates}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This module is a simple text-based demonstration of a more general architecture.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Although the examples use words, the underlying structure is not limited to language. The same kind of Thought-and-Link representation can also support:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch sounds}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch visual patterns}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch actions}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch spatial relationships}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch sequences}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\ltrch Language is used here because it provides an easy way to enter and inspect knowledge.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Tips for use}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Enter short, simple declarative sentences.}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Check the parsed-link display after each entry.}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Use the attribute viewer to see what the system knows or can infer.}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch If the result is not what you expected, inspect the created Link to see how the sentence was interpreted.}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Remember that plural words may be singularized automatically.}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\b\ltrch Examples}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Input:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Dogs are mammals}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Created Link:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? is-a \u8594? mammal]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Input:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Mammals are warm-blooded}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Created Link:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [mammal \u8594? is \u8594? warm-blooded]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Input:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Dogs have fur}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Created Link:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [dog \u8594? has \u8594? fur]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Input:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Fido is a dog}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Created Link:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch [Fido \u8594? is-a \u8594? dog]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Selecting Thought:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Fido}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Possible displayed attributes:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch dog}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch mammal}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch warm-blooded}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch fur}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Summary}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch Use this module to:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch enter knowledge in simple English}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch see how that knowledge is represented internally}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch inspect the attributes of any Thought}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch observe how connected knowledge supports inference}\li1080\ri0\sa160\sb0\jclisttab\tx1080\fi-360\ql\par}
{\fs24\f4 {\ltrch This makes the internal structure of the system visible and easier to understand.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 \li0\ri0\sa160\sb0\fi0\ql\par}
}
}

