\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs40\f3 {\cf2\ltrch Mental Model Module}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch The Mental Model represents the system\rquote s current understanding of its surroundings.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Unlike a traditional grid or map, this model is }{\b\ltrch egocentric and non-linear}{\ltrch .}{\ltrch \line }{\ltrch Objects are represented relative to the system\rquote s point of view, not in fixed coordinates.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch How the Mental Model Works}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch {\*\shppict{\pict\picwgoal9240\pichgoal3868\jpegblip
}}}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 \li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch {\*\shppict{\pict\picwgoal9288\pichgoal3818\jpegblip
}}}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch The display shows how the system organizes perceived objects:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The }{\b\ltrch center}{\ltrch  represents what the system is currently focused on}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The }{\b\ltrch horizontal direction}{\ltrch  represents left/right position (azimuth)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The }{\b\ltrch vertical spread}{\ltrch  loosely reflects elevation}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The }{\b\ltrch density of the grid}{\ltrch  reflects attention and resolution}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Non-linear space}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch The key feature is }{\b\ltrch non-linearity}{\ltrch :}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Objects }{\b\ltrch directly ahead}{\ltrch  are represented with high precision}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Objects }{\b\ltrch far away or peripheral}{\ltrch  are compressed}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Space is not evenly mapped like a Cartesian grid}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch This reflects how real perception works:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch high detail where attention is focused}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch coarse representation elsewhere}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Objects in the Model}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch Each item in the model is a }{\b\ltrch Thought}{\ltrch  linked to the current situation.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Examples from the display:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Sky (far)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Bird Sound (far)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Tree (mid/far)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Fido (mid)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Unknown dog (mid, moving)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Cat (mid, moving)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Bush (mid)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Grass (near)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Each object may include attributes such as:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch distance}{\ltrch  (near, mid, far)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch motion}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch identity or classification}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Key Concepts}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs32\f3 {\cf2\ltrch Egocentric Representation}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\ltrch All positions are relative to the system:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch not absolute coordinates}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch always \ldblquote from here\rdblquote }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs32\f3 {\cf2\ltrch Attention-driven resolution}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The system does not process everything equally}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The center region has the highest detail}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Peripheral areas are simplified}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs32\f3 {\cf2\ltrch Dynamic and transient}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The mental model is continuously updated}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Objects appear, move, and disappear}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Links may decay if not reinforced}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs32\f3 {\cf2\ltrch Unified representation}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\ltrch The same structure used for:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch knowledge (UKS / Thoughts)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch sequences}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch relationships}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch is also used here for perception.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch There is no separate \ldblquote map\rdblquote  data structure.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Controls (Typical Behavior)}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch You can:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Add or simulate objects}{\ltrch  in the environment with the Add to Mental Model dialog}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Move or rotate the system\rquote s position }{\ltrch with arrow keys}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Inspect individual Thoughts}{\ltrch  representing objects}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch View attributes}{\ltrch  such as distance and motion via mouse-over tooltips}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch What This Module Demonstrates}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This module is important because it shows that:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch Perception is not a list of facts}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch It is a }{\b\ltrch structured, spatial, dynamic model}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The system maintains a }{\b\ltrch current situation}{\ltrch , not just stored knowledge}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch This enables:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch prediction (\ldblquote what will move next?\rdblquote )}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch interaction (\ldblquote what should I respond to?\rdblquote )}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch grounding (\ldblquote where is this happening?\rdblquote )}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Why It Is Non-Linear}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch The non-linear layout is intentional:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch real systems (biological or efficient artificial ones) cannot process everything equally}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch resolution must be }{\b\ltrch focused where it matters most}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch this allows fast recognition and response}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Relationship to the Overall Architecture}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch The Mental Model is part of a loop:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Perception \u8594? Mental Model \u8594? Attention \u8594? Prediction \u8594? Evaluation \u8594? Action \u8594? Environment}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch This module specifically represents:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the }{\b\ltrch current state of the world}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch as understood by the system}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch Summary}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch The Mental Model:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch represents the current environment}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch is egocentric and non-linear}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch uses the same Thought/Link structure as all other knowledge}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch supports attention, prediction, and action}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch It is the system\rquote s }{\b\ltrch working view of reality}{\ltrch , not just stored information.}\li0\ri0\sa160\sb0\fi0\ql\par}
}
}

