\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs40\f3 {\cf2\ltrch Add To Mental Model}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This dialog lets you add objects to the current Mental Model (the system\rquote s representation of its immediate environment).}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Enter a Thought (object) and specify its attributes, such as:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch distance}{\ltrch  (near, mid, far) }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch direction / position}{\ltrch  }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch motion}{\ltrch  (if any)  [pending]}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch These attributes are stored as attributes of Links to the object and determine how it appears in the Mental Model display.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch The model is }{\b\ltrch egocentric and non-linear}{\ltrch :}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch positions are relative to the system }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch objects directly ahead are represented with higher detail }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch distant or peripheral objects are compressed }\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Use this dialog to simulate what the system is \ldblquote seeing\rdblquote  or \ldblquote hearing\rdblquote  at the current moment.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 \li0\ri0\sa160\sb0\fi0\ql\par}
}
}

