\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs40\f3 {\cf2\ltrch Learn Melody}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This module demonstrates how the system learns responses to musical phrases using reinforcement learning.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch You may load a phrase file containing named melodies. Each line defines:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch a }{\b\ltrch phrase name}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch an }{\b\ltrch input phrase}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the }{\b\ltrch correct response phrase}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch The file format is:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Name | note:duration note:duration ... => note:duration note:duration ...}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Example (from the included file ):}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch TwinkleTwinkle | 60:500 60:500 67:500 67:500 69:500 69:500 67:1000 => 65:500 65:500 64:500 64:500 62:500 62:500 60:1000}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\ltrch Where:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch 60, 67, etc.}{\ltrch  are MIDI note numbers (pitch)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch 500, 1000, etc.}{\ltrch  are durations in milliseconds}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the left side of => is the }{\b\ltrch input phrase}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the right side is the }{\b\ltrch correct response}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs40\f3 {\cf2\ltrch How learning works}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch After loading the file:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch the system listens for input phrases}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch when a phrase is recognized, it selects a response from known phrases (initially random)}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch if the selected response matches the correct one, well-being increases}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch if not, well-being decreases or remains unchanged}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch Changes in well-being are used to reinforce learning:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch correct responses become more likely over time}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch incorrect responses become less likely}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\ltrch With repeated trials, the system learns the correct response for each input phrase.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs40\f3 {\cf2\ltrch Purpose}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs24\f4 {\ltrch This module demonstrates how the system can:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch learn from experience rather than explicit programming}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch associate inputs with actions based on outcomes}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch improve behavior through reinforcement over time}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
}
}

{\rtf1\ansi\ansicpg1252\uc1\htmautsp\deff2{\fonttbl{\f0\fcharset0 Times New Roman;}{\f2\fcharset0 Segoe UI;}{\f3\fcharset0 Aptos;}{\f4\fcharset0 Aptos Display;}}{\colortbl\red0\green0\blue0;\red255\green255\blue255;\red15\green71\blue97;}\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs24\f3 {\b\ltrch Algorithm Editor Help}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch The Algorithm Editor creates and edits BrainSim Thought tasks. A task is a collection of sequences and contexts stored in the UKS.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch Task Name}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch Enter the task name at the top. When saved, the task and all of its elements are stored under this name.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch Elements Box}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch Enter sequences and contexts as plain text.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch A sequence begins with a name followed by ^.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Example:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Alphabetize_main^}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch   $GetInputParameters}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch   [p1\u8594?SET.IS\u8594?p1.is.spelled]}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch   [p2\u8594?SET.IS\u8594?p2.is.spelled]}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch   ContextWordAlpha}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Each following indented line is a step. A step may be:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3\b {\ltrch [a\u8594?SET.IS\u8594?b]}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch to write a link,}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\b\ltrch SomeOtherSequence  }{\ltrch (a sequence Thought name)}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch to call another sequence,}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch or}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3\b {\ltrch SomeContext}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch to evaluate a context.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch A context begins with its name without ^.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Example:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch ContextWordAlpha}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch   cSameContinue}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch     [cSameContinue\u8594?has\u8594?[p1.is.VLU\u8594?TEST.same\u8594?p2.is.VLU]]}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch     [cSameContinue\u8594?response\u8594?advanceWordLetters]}\li0\ri0\sa0\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Each context contains cases. A case contains one or more has conditions and one response.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch SET Instructions}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch SET.X creates or updates a link of type X.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Example:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch [p1\u8594?SET.IS\u8594?p1.is.NXT]}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch means:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch [p1\u8594?IS\u8594?p1.is.NXT]}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch TEST Conditions}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch TEST.X tests whether a link or virtual relationship exists.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Example:}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch [p1.is\u8594?TEST.NXT\u8594???]}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch tests whether the current value of p1 has a NXT link.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch [p1.is.VLU\u8594?TEST.same\u8594?p2.is.VLU]}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch tests whether both expressions resolve to the same Thought.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch Use NOT.TEST.X to test that a relationship does not exist.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch Indirection}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch Dot notation follows links.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch p1.is}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch means the target of p1\u8594?IS\u8594??.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch p1.is.NXT}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 {\ltrch means follow IS, then follow NXT.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch Search and Replace}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch Use }{\b\ltrch Srch}{\ltrch  to find text in the editor.}{\ltrch \line }{\ltrch Use }{\b\ltrch Repl}{\ltrch  to replace matching text. This is useful for renaming contexts, cases, responses, or variables.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f4 {\cf2\ltrch Save}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f3 {\ltrch Click }{\b\ltrch Save}{\ltrch  to parse and store the task in the UKS. The status line reports whether the task was saved or loaded successfully.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs24\f3 \li0\ri0\sa160\sb0\fi0\ql\par}
}
}

