\loch\hich\dbch\pard\plain\ltrpar\itap0{\lang1033\fs30\f2\cf0 \cf0\ql{\fs40\f3 {\cf2\ltrch Algorithm Module Dialog - User Guide}\li0\ri0\sa80\sb360\fi0\ql\par}
{\fs32\f3 {\cf2\ltrch Overview}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\ltrch The Algorithm Module Dialog allows you to execute predefined tasks (algorithms) with custom parameters. Tasks are stored in the Universal Knowledge Store (UKS) and can perform operations like comparisons, boolean logic, and sequence manipulations.}\li0\ri0\sa160\sb0\fi0\ql\par}
{\fs32\f3 {\cf2\ltrch Dialog Components}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs28\f4 {\cf2\ltrch Task Name Field}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Autocomplete}{\ltrch : Type the first few letters of a task name to see suggestions}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Navigation}{\ltrch : Use Up/Down arrow keys to navigate suggestions}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Selection}{\ltrch : Press Enter or Tab to accept the highlighted suggestion}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\ltrch The dialog automatically searches for tasks that are children of "Task" (excluding "Variable")}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs28\f4 {\cf2\ltrch Parameter Fields}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1 {\b\ltrch Parameter 1}{\ltrch : First input value for the task}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1 {\b\ltrch Parameter 2}{\ltrch : Second input value for the task}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1 {\b\ltrch Flexible Input}{\ltrch : Parameters can be:}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Existing Thought labels (e.g., "TRUE", "FALSE", "dog", "cat")}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Arbitrary strings (automatically created as new Thoughts with spelling sequences)}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs28\f4 {\cf2\ltrch Execute Button}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Keyboard Shortcut}{\ltrch : Press Enter in Parameter 2 field to execute}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Execution}{\ltrch : Runs the selected task with the provided parameters}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\pntext \'B7\tab}{\*\pn\pnlvlblt\pnstart1{\pntxtb\'B7}}{\b\ltrch Status}{\ltrch : Results are displayed in the status bar at the bottom}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs32\f3 {\cf2\ltrch How It Works}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs28\f4 {\cf2\ltrch Task Execution Flow}\li0\ri0\sa80\sb160\fi0\ql\par}
{\fs24\f4 {\listtext 1.\tab}\ls2 {\b\ltrch Parameter Processing}{\ltrch :}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch If parameters don't exist as Thoughts, they are automatically created}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Spelling sequences are generated for new words (each letter becomes a Thought)}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Links are created:\~param1 -> is -> <value1>\~and\~param2 -> is -> <value2>}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext 2.\tab}\ls2 {\b\ltrch Task Lookup}{\ltrch :}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch The system finds the task by name}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch If the task has no "steps" link, it tries\~<taskname>_main}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch This allows tasks to have both a root and a main implementation}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext 3.\tab}\ls2 {\b\ltrch Execution}{\ltrch :}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch The task's sequence of steps is executed}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Contexts are evaluated to determine control flow}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch Links are written to the UKS}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
{\fs24\f4 {\listtext 4.\tab}\ls2 {\b\ltrch Return Value}{\ltrch :}\li720\ri0\sa160\sb0\jclisttab\tx720\fi-360\ql\par}
{\fs24\f4 {\listtext \'B7\tab}\ls1\ilvl1 {\ltrch The result is stored in\~LastLinkWritten}\li1440\ri0\sa160\sb0\jclisttab\tx1440\fi-360\ql\par}
